"""Generated by solo-to-scale; edit `templates/tools/heartbeat.py` in the plugin, then run upgrade.

Heartbeats and budgets. Each role wakes on its own schedule (a cloud scheduled task), works one ticket within
its monthly AI budget, and stops. Policy: founder/heartbeats.json (founder-owned; the `budget` gate).

  python tools/heartbeat.py plan                  # each role's schedule, budget, spend, and its task prompt
  python tools/heartbeat.py start <role>          # budget check, run lock, then resume or claim one ticket
  python tools/heartbeat.py end <role> [--ticket N] [--usd X | --transcript PATH] [--note "..."]
  python tools/heartbeat.py costs [--month YYYY-MM]

`start` exits 0 with a ticket to work on, 2 when there's nothing to do, 6 when the role must not run
(paused, no budget, budget spent, or another run of the role is active) and 5 when GitHub is unclear.
Costs go to one issue per month labelled `cost-log`: AI usage, measured from the session transcript where it
can be, else the policy's flat `fallback_run_usd`, marked estimated. At 80% of a role's budget the log and the
activity log get a warning; at 100% the role stops until next month, or until the founder `/approve`s the
budget request it opens, which adds one more month's budget.
Python 3 standard library plus the gh CLI.
"""
from __future__ import annotations

import argparse
import datetime as dt
import json
import re
import subprocess
import sys
import urllib.parse
from pathlib import Path
from typing import Any

sys.path.insert(0, str(Path(__file__).resolve().parent))
import _s2s as s  # noqa: E402
import approval  # noqa: E402
import tickets  # noqa: E402

OK, IDLE, ERROR, STOP = 0, 2, 5, 6
COST_LOG, RUN_REF = "cost-log", "refs/heartbeats/"
MARK = re.compile(r"<!-- s2s:cost (\{.*?\}) -->")
WARN_AT, STALE_HOURS = 0.8, 6
BUDGET_ROLES = (*tickets.ROLES, "board")
# USD per million tokens; used for models the policy's prices don't name, so it is the most expensive tier.
TOP_PRICE = {"input": 10.0, "output": 50.0, "cache_write": 12.5, "cache_read": 1.0}


# --- policy and cost maths (pure) ------------------------------------------------------------------------

def policy(root: Path = s.ROOT) -> dict[str, Any]:
    try:
        data = json.loads(s.read(root / "founder" / "heartbeats.json") or "{}")
    except ValueError:
        data = {}
    return data if isinstance(data, dict) else {}


def budget(pol: dict[str, Any], role: str) -> float | None:
    v = ((pol.get("roles") or {}).get(role) or {}).get("monthly_budget_usd")
    return float(v) if isinstance(v, (int, float)) and not isinstance(v, bool) and v > 0 else None


def price(pol: dict[str, Any], model: str) -> dict[str, float]:
    for prefix, p in sorted((pol.get("prices_usd_per_mtok") or {}).items(), key=lambda kv: -len(kv[0])):
        if prefix and prefix in (model or ""):
            return {**TOP_PRICE, **p}
    return TOP_PRICE


def transcript_usd(path: Path, pol: dict[str, Any]) -> float | None:
    """API-equivalent cost of a Claude Code session transcript (JSONL). None if it holds no usage."""
    usage: dict[str, tuple[str, dict]] = {}
    try:
        lines = path.read_text(encoding="utf-8").splitlines()
    except OSError:
        return None
    for i, line in enumerate(lines):
        try:
            msg = (json.loads(line) or {}).get("message") or {}
        except ValueError:
            continue
        if isinstance(msg, dict) and isinstance(msg.get("usage"), dict):
            usage[str(msg.get("id") or i)] = (str(msg.get("model") or ""), msg["usage"])  # streamed parts repeat
    if not usage:
        return None
    total = 0.0
    for model, u in usage.values():
        p = price(pol, model)
        total += (int(u.get("input_tokens") or 0) * p["input"] + int(u.get("output_tokens") or 0) * p["output"]
                  + int(u.get("cache_creation_input_tokens") or 0) * p["cache_write"]
                  + int(u.get("cache_read_input_tokens") or 0) * p["cache_read"]) / 1_000_000
    return round(total, 4)


def latest_transcript(root: Path, home: Path | None = None) -> Path | None:
    """The newest Claude Code transcript for this repo (~/.claude/projects/<repo path with - for symbols>/)."""
    base = (home or Path.home()) / ".claude" / "projects" / re.sub(r"[^A-Za-z0-9]", "-", str(root.resolve()))
    found = sorted(base.glob("*.jsonl"), key=lambda p: p.stat().st_mtime) if base.is_dir() else []
    return found[-1] if found else None


def cost_entry(role: str, usd: float, month: str, how: str, ticket: int | None, note: str) -> str:
    data = {"role": role, "usd": round(usd, 4), "month": month, "how": how, **({"ticket": ticket} if ticket else {})}
    head = f"**role:{role}** ${usd:.2f} ({how})" + (f" on #{ticket}" if ticket else "")
    return f"<!-- s2s:cost {json.dumps(data)} -->\n{head}\n\n{tickets.quote(note or 'heartbeat run')}"


def spent(comments: list[dict[str, Any]], month: str) -> dict[str, float]:
    totals: dict[str, float] = {}
    for c in comments:
        m = MARK.search(c.get("body") or "")
        try:
            data = json.loads(m.group(1)) if m else None
        except ValueError:
            data = None
        if not isinstance(data, dict) or data.get("month") != month:
            continue
        usd = data.get("usd")
        if isinstance(usd, (int, float)) and usd >= 0:
            totals[str(data.get("role"))] = totals.get(str(data.get("role")), 0.0) + float(usd)
    return totals


def this_month() -> str:
    return dt.datetime.now(dt.timezone.utc).strftime("%Y-%m")


# --- GitHub ----------------------------------------------------------------------------------------------

class Costs:
    def __init__(self, hub: tickets.Hub, month: str) -> None:
        self.hub, self.month = hub, month

    def log_issue(self, create: bool) -> int | None:
        title = f"Cost log {self.month}"
        found = [i for i in self.hub.tickets("all", COST_LOG) if i.get("title") == title]
        if found or not create:
            return found[0]["number"] if found else None
        return self.hub.api("issues", "-X", "POST", payload={
            "title": title, "labels": [COST_LOG],
            "body": "AI usage cost per role this month, written by `tools/heartbeat.py`. Budgets: "
                    "`founder/heartbeats.json`. A record, never an approval."})["number"]

    def comments(self) -> list[dict[str, Any]]:
        n = self.log_issue(create=False)
        out: list[dict[str, Any]] = []
        page = 1
        while n:
            got = self.hub.api(f"issues/{n}/comments?per_page=100&page={page}") or []
            out += got
            if len(got) < 100:
                break
            page += 1
        return out

    def totals(self) -> dict[str, float]:
        return spent(self.comments(), self.month)


def scope(role: str, month: str) -> str:
    return f"heartbeat:{role}:{month}"


def extra_budgets(hub: tickets.Hub, root: Path, role: str, month: str) -> tuple[int, bool]:
    """(budget requests the founder approved for this role and month, whether one is still open)."""
    pol = approval.policy(root)
    who = approval.founders(pol, hub.repo)
    approved, waiting = 0, False
    for issue in hub.tickets("all", approval.LABEL):
        if f"**Scope:** {scope(role, month)}" not in (issue.get("body") or ""):
            continue
        d = approval.decide(hub.api(f"issues/{issue['number']}/comments?per_page=100") or [], who)
        approved += d["state"] == "approved"
        waiting |= d["state"] == "waiting" and issue.get("state") == "open"
    return approved, waiting


def ask_for_budget(hub: tickets.Hub, root: Path, role: str, month: str, cap: float, used: float) -> None:
    gate = approval.policy(root)["gates"].get("budget") or {}
    if gate.get("mode") != "ask":
        print("the budget gate isn't `ask`: tell the founder in the handoff; no request opened")
        return
    body = approval.request_body(
        "budget", gate.get("what", ""), f"role:{role} has used ${used:.2f} of its ${cap:.2f} AI budget for {month}"
        " and has stopped.", "Approving adds one more month's budget for this role, this month only. Or raise"
        " `monthly_budget_usd` in founder/heartbeats.json, or let it wait for next month.",
        scope(role, month), f"role:{role} (heartbeat)")
    made = hub.api("issues", "-X", "POST", payload={"title": f"[approval] More AI budget for {role} in {month}",
                                                    "body": body, "labels": [approval.LABEL, "gate:budget"]})
    print(f"opened budget request #{made['number']} for the founder")


def standing(hub: tickets.Hub, root: Path, pol: dict[str, Any], role: str, month: str,
             totals: dict[str, float]) -> tuple[float | None, float, float]:
    """(cap, used, base budget). cap is None when the role has no budget."""
    base = budget(pol, role)
    if base is None:
        return None, totals.get(role, 0.0), 0.0
    approved, _ = extra_budgets(hub, root, role, month)
    return base * (1 + approved), totals.get(role, 0.0), base


def run_holder(hub: tickets.Hub, role: str) -> tuple[str, float] | None:
    try:
        ref = hub.api(f"git/ref/{RUN_REF[5:]}{role}")
    except subprocess.CalledProcessError:
        return None
    msg = hub.api(f"git/commits/{ref['object']['sha']}").get("message", "")
    m = re.search(r"at (\d+(?:\.\d+)?)", msg)
    return msg, float(m.group(1)) if m else 0.0


def take_run(hub: tickets.Hub, role: str, now: float) -> bool:
    """One run per role at a time, through a ref like the ticket claim. A lock older than STALE_HOURS is stale."""
    held = run_holder(hub, role)
    if held and now - held[1] < STALE_HOURS * 3600:
        return False
    if held:
        hub.api(f"git/refs/{RUN_REF[5:]}{role}", "-X", "DELETE")
    branch = hub.api("").get("default_branch", "main")
    tree = hub.api(f"commits/{urllib.parse.quote(branch, safe='')}")["commit"]["tree"]["sha"]
    commit = hub.api("git/commits", "-X", "POST", payload={"message": f"heartbeat {role} at {now}", "tree": tree,
                                                         "parents": []})
    try:
        hub.api("git/refs", "-X", "POST", payload={"ref": f"{RUN_REF}{role}", "sha": commit["sha"]})
    except subprocess.CalledProcessError:
        if run_holder(hub, role) is None:
            raise
        return False
    return True


def drop_run(hub: tickets.Hub, role: str) -> None:
    if run_holder(hub, role) is not None:
        hub.api(f"git/refs/{RUN_REF[5:]}{role}", "-X", "DELETE")


# --- commands -----------------------------------------------------------------------------------------

def task_prompt(role: str) -> str:
    return (f"You are the {role} role. Run the solo-to-scale `heartbeat` skill for role {role}: "
            f"`python tools/heartbeat.py start {role}`, work only the ticket it gives you, then end the run.")


def cmd_plan(a: argparse.Namespace, hub: tickets.Hub, pol: dict[str, Any]) -> int:
    month = a.month or this_month()
    totals = Costs(hub, month).totals()
    print(f"| Role | Heartbeat | Schedule (cron, UTC) | Budget {month} | Spent |\n| --- | --- | --- | --- | --- |")
    for role in BUDGET_ROLES:
        cfg = (pol.get("roles") or {}).get(role) or {}
        b = budget(pol, role)
        on = "on" if cfg.get("enabled") and role in tickets.ROLES else "off"
        print(f"| {role} | {on} | {cfg.get('cron') or '-'} | {f'${b:.2f}' if b else 'not set'} | "
              f"${totals.get(role, 0):.2f}" + (f" ({totals.get(role, 0) / b:.0%})" if b else "") + " |")
    print("\nOne cloud scheduled task per role that is on, on its schedule, in this repo:")
    for role in tickets.ROLES:
        if ((pol.get("roles") or {}).get(role) or {}).get("enabled"):
            print(f"- {role}: \"{task_prompt(role)}\"")
    return OK


def cmd_start(a: argparse.Namespace, hub: tickets.Hub, pol: dict[str, Any]) -> int:
    tickets.need_role(a.role)
    cfg = (pol.get("roles") or {}).get(a.role) or {}
    if not cfg.get("enabled"):
        print(f"stop: role:{a.role}'s heartbeat is off in founder/heartbeats.json")
        return STOP
    month = a.month or this_month()
    cap, used, _ = standing(hub, a.root, pol, a.role, month, Costs(hub, month).totals())
    if cap is None:
        print(f"stop: role:{a.role} has no monthly_budget_usd in founder/heartbeats.json; the founder sets it")
        return STOP
    if used >= cap:
        print(f"stop: role:{a.role} has used ${used:.2f} of ${cap:.2f} for {month}: budget spent")
        if not extra_budgets(hub, a.root, a.role, month)[1]:
            ask_for_budget(hub, a.root, a.role, month, cap, used)
        return STOP
    if not take_run(hub, a.role, a.now or dt.datetime.now(dt.timezone.utc).timestamp()):
        print(f"stop: another role:{a.role} run is active; this one does nothing")
        return STOP
    print(f"budget: ${used:.2f} of ${cap:.2f} used for {month}; ${cap - used:.2f} left"
          + (" (WARNING: over 80%; keep this run small)" if used >= WARN_AT * cap else ""))
    try:
        return pick(a, hub)
    except Exception:
        drop_run(hub, a.role)  # an unclear GitHub reply leaves no run lock behind
        raise


def pick(a: argparse.Namespace, hub: tickets.Hub) -> int:
    mine = [t for t in hub.tickets("open") if tickets.role_of(t) == a.role]
    for t in mine:
        if tickets.CLAIMED in tickets.labels_of(t) and hub.holder(t["number"]) == f"role:{a.role}":
            print(f"resume #{t['number']}: {t.get('title', '')}")
            return OK
    for t in mine:
        if tickets.CLAIMED in tickets.labels_of(t) or tickets.BLOCKED in tickets.labels_of(t):
            continue
        claim = argparse.Namespace(n=t["number"], role=a.role, why="heartbeat run")
        if tickets.cmd_claim(claim, hub) == tickets.OK:
            print(f"work on #{t['number']}: {t.get('title', '')}")
            return OK
    drop_run(hub, a.role)
    print(f"nothing to do: no ready ticket for role:{a.role}. End the run now; `end` records its cost.")
    return IDLE


def cmd_end(a: argparse.Namespace, hub: tickets.Hub, pol: dict[str, Any]) -> int:
    if a.role not in BUDGET_ROLES:
        raise SystemExit(f"unknown role {a.role!r}; roles: {', '.join(BUDGET_ROLES)}")
    month = a.month or this_month()
    if a.usd is not None:
        usd, how = a.usd, "reported"
    else:
        path = a.transcript or latest_transcript(a.root)
        usd = transcript_usd(path, pol) if path else None
        how = "measured"
        if usd is None:
            usd, how = float(pol.get("fallback_run_usd") or 2.0), "estimated"
    if usd < 0:
        raise SystemExit("--usd can't be negative")
    costs = Costs(hub, month)
    before = costs.totals()
    hub.comment(costs.log_issue(create=True), cost_entry(a.role, usd, month, how, a.ticket, a.note))
    cap, used, _ = standing(hub, a.root, pol, a.role, month, {**before, a.role: before.get(a.role, 0) + usd})
    print(f"recorded ${usd:.2f} ({how}) for role:{a.role}; {month}: ${used:.2f}" + (f" of ${cap:.2f}" if cap else ""))
    if cap:
        was = before.get(a.role, 0)
        for mark, word in ((1.0, "spent: the role stops until next month or the founder approves more"),
                           (WARN_AT, "over 80%")):
            if was < mark * cap <= used:
                why = f"${used:.2f} of ${cap:.2f} for {month}: {word}."
                print(f"budget {word}")
                hub.comment(costs.log_issue(create=True), f"**role:{a.role}** budget warning\n\n{tickets.quote(why)}")
                if a.ticket:
                    hub.record(a.ticket, a.role, "budget warning", why)
                break
    if a.ticket and hub.holder(a.ticket) == f"role:{a.role}" and hub.issue(a.ticket).get("state") == "open":
        print(f"note: #{a.ticket} is still claimed by role:{a.role}. Next run resumes it; release or hand it off"
              " if you won't.")
    drop_run(hub, a.role)
    return OK


def cmd_costs(a: argparse.Namespace, hub: tickets.Hub, pol: dict[str, Any]) -> int:
    month = a.month or this_month()
    totals = Costs(hub, month).totals()
    for role in BUDGET_ROLES:
        cap, used, _ = standing(hub, a.root, pol, role, month, totals)
        flag = "" if not cap else " STOPPED" if used >= cap else " WARN" if used >= WARN_AT * cap else ""
        print(f"{role}: ${used:.2f}" + (f" of ${cap:.2f} ({used / cap:.0%}){flag}" if cap else " (no budget set)"))
    print(f"total {month}: ${sum(totals.values()):.2f}")
    return OK


def main(argv: list[str] | None = None) -> int:
    common = argparse.ArgumentParser(add_help=False)
    common.add_argument("--root", type=Path, default=s.ROOT, help=argparse.SUPPRESS)
    common.add_argument("--month", default="", help=argparse.SUPPRESS)
    ap = argparse.ArgumentParser(description="Heartbeats and budgets")
    sub = ap.add_subparsers(dest="cmd", required=True)
    sub.add_parser("plan", parents=[common])
    sub.add_parser("costs", parents=[common])
    p = sub.add_parser("start", parents=[common])
    p.add_argument("role")
    p.add_argument("--now", type=float, default=0, help=argparse.SUPPRESS)
    p = sub.add_parser("end", parents=[common])
    p.add_argument("role")
    p.add_argument("--ticket", type=int)
    p.add_argument("--usd", type=float)
    p.add_argument("--transcript", type=Path)
    p.add_argument("--note", default="")
    a = ap.parse_args(argv)
    pol = policy(a.root)
    if not pol.get("roles"):
        print("founder/heartbeats.json is missing or has no roles: no heartbeat runs")
        return STOP
    repo = approval.repo_name(a.root)
    if not repo:
        print("can't tell which GitHub repo this is: nothing done")
        return ERROR
    run = {"plan": cmd_plan, "start": cmd_start, "end": cmd_end, "costs": cmd_costs}[a.cmd]
    try:
        return run(a, tickets.Hub(repo), pol)
    except (subprocess.CalledProcessError, FileNotFoundError, ValueError, KeyError, TypeError) as exc:
        print(f"GitHub unavailable or unexpected reply ({type(exc).__name__}): stop; nothing more is done")
        return ERROR


if __name__ == "__main__":
    sys.exit(main())
